Translate the following GNU C++14 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <cstdio>
#include <algorithm>
#include <vector>
#define pair_ll pair<long long, long long>
using namespace std;

long long comb[62][62], A[32][32], B[32][32], totalComb;
int row, col, total;
char pattern[110];
long long countComb[32][32], maxDiff;
vector<pair_ll> P[32][2], Q[32][2];

void addPath(int x, int y, long long g, long long c1, long long c2, int ck) {
    if (x + y == row + total) {
        P[x][ck].push_back({g, c1});
        if (c2) Q[x][ck].push_back({g, c2});
        return;
    }
    addPath(x + 1, y, g + (!ck ? A[x + 1][y] : 0), c1, (pattern[x + y] != 'B' ? c2 : 0), ck);
    addPath(x, y + 1, g + (ck ? B[x][y + 1] : 0), c1, (pattern[x + y] != 'A' ? c2 : 0), ck);
}

void computeMin(int x, int y, long long g, int ck) {
    if (x + y == row + total) {
        if (P[x][ck].empty()) return;
        int t = lower_bound(P[x][ck].begin(), P[x][ck].end(), pair_ll((totalComb + 1) / 2 - g, 0)) - P[x][ck].begin();
        if (t != P[x][ck].size() && P[x][ck][t].second > 0) {
            long long tp = (P[x][ck][t].first + g) * 2 - totalComb;
            if (tp < 0) tp = -tp;
            if (maxDiff > tp) maxDiff = tp;
        }
        if (t && P[x][ck][t - 1].second > 0) {
            long long tp = (P[x][ck][t - 1].first + g) * 2 - totalComb;
            if (tp < 0) tp = -tp;
            if (maxDiff > tp) maxDiff = tp;
        }
        return;
    }
    computeMin(x - 1, y, g + (!ck ? A[x][y] : 0), ck);
    computeMin(x, y - 1, g + (ck ? B[x][y] : 0), ck);
}

long long totalResult;

void computeMax(int x, int y, long long g, int ck) {
    if (x + y == row + total) {
        int t = lower_bound(Q[x][ck].begin(), Q[x][ck].end(), pair_ll((totalComb + 1) / 2 - g, 0)) - Q[x][ck].begin();
        if (t != Q[x][ck].size() && Q[x][ck][t].second > 0) {
            long long tp = (Q[x][ck][t].first + g) * 2 - totalComb;
            if (tp < 0) tp = -tp;
            if (maxDiff == tp) {
                totalResult += Q[x][ck][t].second;
            }
        }
        if (t && Q[x][ck][t - 1].second > 0) {
            long long tp = (Q[x][ck][t - 1].first + g) * 2 - totalComb;
            if (tp < 0) tp = -tp;
            if (maxDiff == tp) {
                totalResult += Q[x][ck][t - 1].second;
            }
        }
        return;
    }
    if (pattern[x + y - 1] != 'B') computeMax(x - 1, y, g + (!ck ? A[x][y] : 0), ck);
    if (pattern[x + y - 1] != 'A') computeMax(x, y - 1, g + (ck ? B[x][y] : 0), ck);
}

void compress(vector<pair_ll>& P) {
    if (P.empty()) return;
    sort(P.begin(), P.end());
    int count = 0;
    long long sum = 0;
    for (size_t i = 0; i < P.size(); i++) {
        sum += P[i].second;
        if (i == P.size() - 1 || P[i].first != P[i + 1].first) {
            P[count++] = {P[i].first, sum};
            sum = 0;
        }
    }
    P.resize(count);
}

int main() {
    int i, j;
    scanf("%d%d", &row, &col);
    scanf("%s", pattern);
    for (i = 0; i <= 60; i++) {
        comb[i][0] = 1;
        for (j = 1; j <= i; j++) comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
    }
    total = row + col;
    totalComb = comb[total * 2][row * 2];
    for (i = 0; i <= total; i++) {
        for (j = 0; j <= total; j++) {
            if (i) A[i][j] = comb[i - 1][row - 1] * (comb[total * 2 - i][row] - comb[j][row]);
            if (j) B[i][j] = comb[j - 1][row - 1] * (comb[total * 2 - j][row] - comb[i][row]);
        }
    }
    memset(countComb, 0, sizeof(countComb));
    countComb[0][0] = 1;
    for (i = 0; i <= total; i++) {
        for (j = 0; j <= total; j++) {
            if (i != total && pattern[i + j] != 'B') countComb[i + 1][j] += countComb[i][j];
            if (j != total && pattern[i + j] != 'A') countComb[i][j + 1] += countComb[i][j];
        }
    }
    for (i = row; i <= total; i++) {
        if (pattern[i + row - 1] != 'B') addPath(row, i, A[row][i], comb[i + row - 1][row - 1], countComb[row - 1][i], 0);
        if (pattern[i + row - 1] != 'A') addPath(i, row, B[i][row], comb[i + row - 1][row - 1], countComb[i][row - 1], 1);
    }
    for (i = row; i <= total; i++) {
        for (j = 0; j < 2; j++) {
            compress(P[i][j]);
            compress(Q[i][j]);
        }
    }
    maxDiff = totalComb + 1;
    computeMin(total, total, 0, 0);
    computeMin(total, total, 0, 1);
    computeMax(total, total, 0, 0);
    computeMax(total, total, 0, 1);
    printf("%lld\n", totalResult);
}
